  "implementation": "def solve(case):
    import collections

    # Validate input
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    nodes = case.get('nodes')
    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    required_symbols = case.get('required_symbols')
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")

    # Build lookup dict and children map
    node_dict = {}
    children_map = collections.defaultdict(list)
    root_id = None
    for n in nodes:
        nid = n.get('id')
        if nid is None:
            raise ValueError("node missing id")
        node_dict[nid] = n
        parent = n.get('parent')
        if parent is None:
            if root_id is not None:
                raise ValueError("multiple roots")
            root_id = nid
        else:
            children_map[parent].append(nid)
    if root_id is None:
        raise ValueError("no root node")

    # Initialise retained set and symbol counts
    retained = set(node_dict.keys())
    symbol_counts = collections.Counter()
    for n in nodes:
        symbol_counts[n['symbol']] += 1
    required_symbols_set = set(required_symbols)
    removed_order = []

    # Sorted list of node ids by depth descending, then id ascending
    sorted_nodes = sorted(node_dict.keys(),
                          key=lambda nid: (-node_dict[nid]['depth'], nid))

    # Loop until no more removals
    changed = True
    while changed:
        changed = False
        for nid in sorted_nodes:
            if nid not in retained:
                continue
            node = node_dict[nid]
            if not node.get('removable', False):
                continue
            if nid == root_id:
                continue
            # Check if any child is retained
            children = children_map.get(nid, [])
            has_child = any(cid in retained for cid in children)
            if has_child:
                continue
            # Tentatively remove: check required symbols remain
            sym = node['symbol']
            symbol_counts[sym] -= 1
            feasible = all(symbol_counts[rs] > 0 for rs in required_symbols_set)
            if feasible:
                retained.remove(nid)
                removed_order.append(nid)
                changed = True
            else:
                symbol_counts[sym] += 1

    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }"
}
